def main() -> int:
    parser = argparse.ArgumentParser(description="Verify D1 SQL with Python sqlite3.")
    parser.add_argument(
        "--schema",
        action="append",
        help="D1 schema SQL file; repeat to override the default full migration chain",
    )
    parser.add_argument(
        "--seed",
        action="append",
        help="Optional seed SQL file; repeat to execute multiple seed files",
    )
    args = parser.parse_args()

    schema_paths = (
        [Path(value) for value in args.schema]
        if args.schema
        else sorted(Path("migrations/d1").glob("*.sql"))
    )
    if not schema_paths:
        raise SystemExit("no D1 schema migrations found")
    for schema_path in schema_paths:
        if not schema_path.exists():
            raise SystemExit(f"schema file not found: {schema_path}")

    lease_guard_verified = False
    segment_guard_verified = False
    relay_owner_guard_verified = False
    relay_container_operation_verified = False
    relay_container_operation_rollout_verified = False
    relay_container_financial_terminal_verified = False
    relay_container_financial_terminal_rollout_verified = False
    relay_container_reconciliation_observer_verified = False
    relay_container_reconciliation_observer_rollout_verified = False
    relay_container_r2_inventory_verified = False
    relay_container_r2_inventory_rollout_verified = False
    relay_container_reconciliation_retry_apply_verified = False
    relay_container_reconciliation_retry_apply_rollout_verified = False
    relay_container_financial_terminal_enforce_verified = False
    relay_container_financial_terminal_enforce_rollout_verified = False
    relay_container_provider_egress_grant_verified = False
    relay_container_provider_egress_grant_rollout_verified = False
    relay_container_provider_usage_receipt_verified = False
    relay_container_provider_usage_receipt_rollout_verified = False
    relay_container_provider_usage_binding_verified = False
    relay_container_provider_usage_binding_rollout_verified = False
    relay_container_atomic_admission_verified = False
    relay_container_atomic_admission_rollout_verified = False
    relay_container_scheduled_terminalization_verified = False
    relay_container_scheduled_terminalization_rollout_verified = False
    relay_container_response_artifacts_verified = False
    relay_container_response_artifacts_rollout_verified = False
